-- Manually reviewed labelled product identities. Not automatic barcode matching or buying approval.
DO $$
DECLARE r record; o record; c record; m record; master_id bigint;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"asin": "B08NFBB83S", "supplier": "Sweet & Glory", "sku": "NERD027", "supplier_ean": "0079200774479", "supplier_title": "Nerds Big Chewy Theatre 120g", "case_qty": 12, "unit_size": "120g", "master_title": "Nerds Big Chewy Theatre Box 120g", "brand": "Nerds", "variant": "Big Chewy", "candidate_title": "Big Chewy NERDS Soft Crunchy Candy Large Box American Sweets 2 x 120g", "pack_qty": 2, "reuse_master": 62, "listing_ean": "", "upc": "", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 2, "supplier_case_qty": 12, "supplier_offer_id": "530", "verifiedSupplierProductId": "NERD027", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B08NFBB83S", "amazon_captured_at": "2026-10-25T23:08:54.670752+00:00", "amazon_labelled_facts": {"Brand Name": "NERDS", "Flavour": "Fruity", "Container Type": "Box", "ASIN": "B08NFBB83S", "Unit Count": "240 gram", "Number of Items": "2", "Item Weight": "120 Grams", "Item Package Quantity": "2", "Number of Pieces": "2", "Package Size Name": "Big", "Size": "120 g (Pack of 2)"}, "supplier_source": "https://sweetandglory.com/brands/n-p/nerds-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Two 120g theatre boxes per Amazon sale: total 240g. Reuse existing Big Chewy 120g master and verified Sweet & Glory supplier link; 12 supplier boxes yield six Amazon two-packs. No assembled-pack barcode was exposed.", "commercial_approved": false, "supplier_barcode_verified": true}}, {"asin": "B00RW65P5A", "supplier": "Sweet & Glory", "sku": "KRAFT009", "supplier_ean": "", "supplier_title": "Kraft Hickory Smoke BBQ Sauce 496g", "case_qty": 12, "unit_size": "496g", "master_title": "Kraft Hickory Smoke BBQ Sauce 496g", "brand": "Kraft", "variant": "Hickory Smoke", "candidate_title": "Kraft Slow-Simmered Hickory Smoke Barbecue Sauce 496g", "pack_qty": 1, "reuse_master": null, "listing_ean": "0021000052295", "upc": "021000052295", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "554", "verifiedSupplierProductId": "KRAFT009", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B00RW65P5A", "amazon_captured_at": "2026-10-25T23:08:54.608634+00:00", "amazon_labelled_facts": {"Flavour": "Hickory Smoke,Hickory", "Brand Name": "Kraft", "Container Type": "Bottle", "Global Trade Identification Number": "00021000052295", "UPC": "021000052295", "ASIN": "B00RW65P5A", "Item Weight": "0.54 Kilograms", "Unit Count": "496 gram", "Number of Items": "1", "Number of Pieces": "1", "Size": "496 g (Pack of 1)"}, "supplier_source": "https://sweetandglory.com/brands/i-m/kraft-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Kraft Hickory Smoke sauce, one 496g bottle. Amazon retail UPC is explicit; supplier barcode remains unknown. Identity established from product brand, Hickory Smoke variant, 496g and bottle format plus the exact stored supplier SKU. Supplier page independently corroborates KRAFT009 and 12ct.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_upc": "021000052295"}}, {"asin": "B002E2N43C", "supplier": "Wholesale Sweets", "sku": "millions-jar-strawberry", "supplier_ean": "", "supplier_title": "Millions Strawberry Flavour - 1 x 2.27kg Jar", "case_qty": 1, "unit_size": "2.27kg", "master_title": "Millions Strawberry Flavour - 1 x 2.27kg Jar", "brand": "Millions", "variant": "Strawberry", "candidate_title": "Millions Jar Strawberry 2.27 Kg", "pack_qty": 1, "reuse_master": null, "listing_ean": "", "upc": "", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 1, "supplier_offer_id": "5484", "verifiedSupplierProductId": "millions-jar-strawberry", "verifiedSupplier": "Wholesale Sweets", "amazon_url": "https://www.amazon.co.uk/dp/B002E2N43C", "amazon_captured_at": "2026-10-25T23:09:03.883311+00:00", "amazon_labelled_facts": {"Brand Name": "Millions", "Flavour": "Strawberry", "Container Type": "Jar", "ASIN": "B002E2N43C", "Unit Count": "2270.0 gram", "Number of Items": "1", "Item Weight": "2.27 Kilograms", "Item Package Quantity": "1", "Package Size Name": "2.27 kg", "Size": "2.27 kg (Pack of 1)"}, "supplier_source": "https://www.wholesalesweets.co.uk/millions-jar-strawberry", "supplier_record_last_seen_at": "2026-10-24T18:58:24.669Z", "review_notes": "One original Millions Strawberry 2.27kg jar. Exact brand, flavour, jar format and quantity agree with saved supplier record. No Amazon or supplier retail barcode exposed. Supplier page could not be refreshed; stored quote/stock remain historical.", "commercial_approved": false, "supplier_barcode_verified": false}}, {"asin": "B003T3QKA4", "supplier": "Wholesale Sweets", "sku": "millions-jar-bubblegum", "supplier_ean": "", "supplier_title": "Millions Bubblegum Jar 2.27kg", "case_qty": 1, "unit_size": "2.27kg", "master_title": "Millions Bubblegum Jar 2.27kg", "brand": "Millions", "variant": "Bubblegum", "candidate_title": "Millions Jar Bubblegum Flavour 2.27 Kg", "pack_qty": 1, "reuse_master": null, "listing_ean": "", "upc": "", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 1, "supplier_offer_id": "5462", "verifiedSupplierProductId": "millions-jar-bubblegum", "verifiedSupplier": "Wholesale Sweets", "amazon_url": "https://www.amazon.co.uk/dp/B003T3QKA4", "amazon_captured_at": "2026-10-25T23:09:03.835310+00:00", "amazon_labelled_facts": {"Flavour": "Fruit", "Brand Name": "Millions", "Container Type": "Jar", "ASIN": "B003T3QKA4", "Item Weight": "2.27 Kilograms", "Unit Count": "2270.0 gram", "Item Package Quantity": "1", "Number of Items": "1", "Number of Pieces": "1", "Package Size Name": "2.27 kg", "Size": "2.27 kg (Pack of 1)"}, "supplier_source": "https://www.wholesalesweets.co.uk/millions-jar-bubblegum", "supplier_record_last_seen_at": "2026-10-24T18:58:24.669Z", "review_notes": "One original Millions Bubblegum 2.27kg jar. Title establishes Bubblegum despite generic Fruit flavour metadata. Brand, jar format, weight and single pack agree with saved supplier record. No retail barcode exposed; supplier page no longer exposes product details, so quote/stock are historical.", "commercial_approved": false, "supplier_barcode_verified": false}}, {"asin": "B01LTIQ3V6", "supplier": "Wholesale Sweets", "sku": "millions-jar-cola", "supplier_ean": "", "supplier_title": "Millions Cola Jar 2.27kg", "case_qty": 1, "unit_size": "2.27kg", "master_title": "Millions Cola Jar 2.27kg", "brand": "Millions", "variant": "Cola", "candidate_title": "Millions Jar Cola 2.27 Kg", "pack_qty": 1, "reuse_master": null, "listing_ean": "", "upc": "", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 1, "supplier_offer_id": "5465", "verifiedSupplierProductId": "millions-jar-cola", "verifiedSupplier": "Wholesale Sweets", "amazon_url": "https://www.amazon.co.uk/dp/B01LTIQ3V6", "amazon_captured_at": "2026-10-25T23:09:08.689318+00:00", "amazon_labelled_facts": {"Brand Name": "Millions", "Container Type": "Jar", "ASIN": "B01LTIQ3V6", "Unit Count": "2270.0 gram", "Number of Items": "1", "Item Weight": "2.27 Kilograms", "Item Package Quantity": "1", "Number of Pieces": "1", "Package Size Name": "2.27 kg", "Size": "2.27 kg (Pack of 1)"}, "supplier_source": "https://www.wholesalesweets.co.uk/millions-jar-cola", "supplier_record_last_seen_at": "2026-10-24T18:58:24.669Z", "review_notes": "One original Millions Cola 2.27kg jar. Exact brand, Cola title, jar format, weight and single pack agree with saved supplier record. No retail barcode exposed; supplier page refresh did not expose product details, so quote/stock are historical.", "commercial_approved": false, "supplier_barcode_verified": false}}, {"asin": "B0CTVHB9Z6", "supplier": "The Kandy King", "sku": "190075", "supplier_ean": "", "supplier_title": "Nerds Gummy Clusters Very Berry Family Pack USA (5x524g)", "case_qty": 5, "unit_size": "524g", "master_title": "Nerds Gummy Clusters Very Berry 524g Bag", "brand": "Nerds", "variant": "Gummy Clusters Very Berry", "candidate_title": "Nerds Gummy Clusters Candy, Very Berry, Resealable 18.5 Ounce Big Bag", "pack_qty": 1, "reuse_master": null, "listing_ean": "0079200082277", "upc": "079200082277", "evidence": {"method": "labelled_product_review_batch3_2026_10_25", "identity_basis": "Manual review of explicit brand, product variant, unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 5, "supplier_offer_id": "71431", "verifiedSupplierProductId": "190075", "verifiedSupplier": "The Kandy King", "amazon_url": "https://www.amazon.co.uk/dp/B0CTVHB9Z6", "amazon_captured_at": "2026-10-25T23:09:08.598894+00:00", "amazon_labelled_facts": {"Brand Name": "Nerds", "Flavour": "Very Berry", "Container Type": "Bag", "UPC": "079200082277", "Global Trade Identification Number": "00079200082277", "ASIN": "B0CTVHB9Z6", "Unit Count": "1 count", "Number of Items": "1", "Item Weight": "18.5 Ounces", "Item Package Quantity": "1", "Number of Pieces": "1", "Package Size Name": "18.5 oz", "Size": "18.5 Ounce (Pack of 1)"}, "supplier_source": "https://www.thekandyking.co.uk/nerds-gummy-clusters-very-berry-family-pack-5x524g/", "supplier_record_last_seen_at": "2026-10-24T19:03:53.119Z", "review_notes": "One Very Berry resealable 18.5oz bag per Amazon sale. 18.5oz is 524.466g, corresponding to the saved supplier 524g unit label; supplier case is five bags. Specific unit conversion only, no parser tolerance change. Amazon retail UPC is explicit but supplier retail barcode remains unknown; supplier page could not be independently refreshed. Commercial hold remains, including unknown VAT and supplier price.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_upc": "079200082277"}}]'::jsonb) AS t(asin text,supplier text,sku text,supplier_ean text,supplier_title text,case_qty integer,unit_size text,master_title text,brand text,variant text,candidate_title text,pack_qty integer,reuse_master bigint,listing_ean text,upc text,evidence jsonb)
 LOOP
  SELECT so.*,s.name supplier INTO STRICT o FROM supplier_offers so JOIN suppliers s ON s.id=so.supplier_id WHERE s.name=r.supplier AND so.supplier_product_id=r.sku;
  SELECT * INTO STRICT c FROM amazon_catalogue_candidates WHERE asin=r.asin;
  IF NOT o.is_active OR o.product<>r.supplier_title OR coalesce(o.ean,'')<>r.supplier_ean OR o.size<>r.unit_size OR o.case_qty<>r.case_qty OR c.title<>r.candidate_title THEN RAISE EXCEPTION 'Evidence changed: %',r.asin; END IF;
  IF c.match_status NOT IN ('unmatched','verified') OR (c.match_status='verified' AND coalesce(c.match_evidence->>'method','')<>'labelled_product_review_batch3_2026_10_25') THEN RAISE EXCEPTION 'Existing decision requires review: %',r.asin; END IF;
  IF r.upc<>'' AND EXISTS(SELECT 1 FROM unnest(ARRAY[c.ean,c.upc,c.gtin]) code WHERE coalesce(code,'')<>'' AND lpad(code,14,'0')<>lpad(r.upc,14,'0')) THEN RAISE EXCEPTION 'Existing barcode conflict: %',r.asin; END IF;
  master_id:=r.reuse_master;
  IF master_id IS NOT NULL THEN
   SELECT * INTO STRICT m FROM master_product_identities WHERE id=master_id;
   IF m.product_name<>r.master_title OR m.unit_size<>r.unit_size OR m.status<>'verified' THEN RAISE EXCEPTION 'Reused master changed: %',r.asin; END IF;
  ELSE
   IF (SELECT count(*) FROM master_product_identities WHERE asin=r.asin)>1 THEN RAISE EXCEPTION 'Duplicate masters: %',r.asin; END IF;
   SELECT id INTO master_id FROM master_product_identities WHERE asin=r.asin;
   IF master_id IS NULL THEN
    INSERT INTO master_product_identities(product_name,brand,variant,size,unit_size,ean,asin,status,canonical_key)
    VALUES(r.master_title,r.brand,r.variant,r.unit_size,r.unit_size,r.listing_ean,r.asin,'verified',lower(r.brand||'|'||r.variant||'|'||r.unit_size)) RETURNING id INTO master_id;
   END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM product_identity_offers WHERE supplier=r.supplier AND supplier_offer_id=r.sku AND identity_id<>master_id) OR EXISTS(SELECT 1 FROM amazon_product_listings WHERE marketplace='UK' AND asin=r.asin AND (identity_id<>master_id OR pack_qty<>r.pack_qty)) THEN RAISE EXCEPTION 'Conflicting relationship: %',r.asin; END IF;
  INSERT INTO product_identity_offers(identity_id,supplier,supplier_offer_id,match_score,match_status,match_reason)
  VALUES(master_id,r.supplier,r.sku,100,'verified','2026-10-25 labelled product review: '||r.evidence::text) ON CONFLICT(supplier,supplier_offer_id) DO NOTHING;
  INSERT INTO amazon_product_listings(identity_id,asin,ean,pack_qty,unit_size,title,marketplace,status)
  VALUES(master_id,r.asin,r.listing_ean,r.pack_qty,r.unit_size,c.title,'UK','verified') ON CONFLICT(marketplace,asin) DO NOTHING;
  UPDATE amazon_catalogue_candidates SET match_status='verified',matched_master_identity_id=master_id,matched_supplier_offer_id=o.id,match_score=100,upc=coalesce(nullif(upc,''),nullif(r.upc,'')),match_evidence=coalesce(match_evidence,'{}'::jsonb)||r.evidence,updated_at=now() WHERE asin=r.asin AND match_status='unmatched';
 END LOOP;
END $$;
